const expand = (text: string): string => text.replace(/\uE000(.)\*(\d+)\uE000/gu, (_m, ch: string, n: string) => ch.repeat(Number(n)));

type Args = Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any

const CALLS: Record<string, (a: Args) => unknown> = {
  clipCommandOutput: (a) => clipCommandOutput(a['text'], a['budget']),
  clipText: (a) => clipText(a['text'], a['budget'], a['hint']),
  visibleHtml: (a) => visibleHtml(a['html']),
  isHtmlContent: (a) => isHtmlContent(a['contentType'], a['text']),
  repeatNote: (a) => repeatNote(a['call']),
  isRepeatNote: (a) => isRepeatNote(a['text']),
  clearedToolResultNote: (a) => clearedToolResultNote(a['chars']),
  isClearedToolResult: (a) => isClearedToolResult(a['text']),
  clearOldToolResults: (a) => clearOldToolResults(a['messages'], a['policy']),
  contextClearingFromEnv: (a) => contextClearingFromEnv(a['env']),
  estimateTokens: (a) => estimateTokens(a['text']),
  classify: (a) => ({ complexity: classifyComplexity(a['prompt'], a['tokens'] ?? estimateTokens(a['prompt'])), risk: classifyRisk(a['prompt']), task: classifyTask(a['prompt']) }),
  estimateCost: (a) => estimateCost(a['profile'], a['usage']),
  aggregateModelStats: (a) => aggregateModelStats(a['observations']),
  routeModel: (a) => {
    const decision = routeModel(a['profiles'], a['request'], a['stats']);
    // 고른 모델은 입력 배열의 같은 객체여야 한다
    for (const candidate of decision.candidates) expect(a['profiles']).toContain(candidate.model);
    return { ...decision, selected: a['profiles'].indexOf(decision.selected), candidates: decision.candidates.map((candidate) => ({ ...candidate, model: a['profiles'].indexOf(candidate.model) })) };
  },
  validateModelProfiles: (a) => validateModelProfiles(a['input']),
  routeCliTier: (a) => routeCliTier(a['request']),
  tiers: (a) => ({ higher: higherCliTier(a['a'], a['b']), next: nextCliTier(a['b']), label: tierLabel(a['b']) }),
};

describe('토큰 예산·모델 선택 벡터(옛 TS 구현이 낸 값)', () => {
  it(`벡터 ${VECTORS.length}개`, () => {
    const failures: string[] = [];
    VECTORS.forEach(([fn, args, expected], index) => {
      const input = decodeNative<Args>(expand(args));
      let actual: string;
      try {
        actual = `ok:${String(encodeNative(CALLS[fn]!(input)))}`;
      } catch (error) {
        actual = `err:${(error as Error).message}`;
      }
      if (actual !== expand(expected)) failures.push(`#${index} ${fn}\n입력: ${expand(args).slice(0, 400)}\n기대: ${expand(expected).slice(0, 600)}\n실제: ${actual.slice(0, 600)}`);
    });
    expect(failures.join('\n---\n')).toBe('');
  });

  it('함수마다 벡터가 있다', () => {
    const covered = new Set(VECTORS.map(([fn]) => fn));
    for (const fn of Object.keys(CALLS)) expect(covered.has(fn), fn).toBe(true);
  });
});

describe('의도한 차이와 참조', () => {
  const profile = (id: string, over: Partial<ModelProfile> = {}): ModelProfile => ({
    id,
    provider: 'anthropic',
    model: id,
    label: id,
    capabilities: ['tools'],
    contextWindow: 200000,
    pricing: { inputPerMillion: 3, outputPerMillion: 15 },
    baselineQuality: 0.8,
    baselineLatencyMs: 4000,
    ...over,
  });

  it('서로게이트 쌍을 가르는 자르기는 U+FFFD가 된다(옛 구현은 짝 없는 서로게이트를 남겼다)', () => {
    const clipped = clipCommandOutput('🙂'.repeat(20), 11);
    expect(clipped.isWellFormed()).toBe(true);
    expect(clipped).toContain('\uFFFD');
    expect(clipped).toContain('전체 40자 중 29자 생략');
    // 쌍이 온전하면 그대로다
    expect(clipCommandOutput('🙂'.repeat(20), 8)).not.toContain('\uFFFD');
    // 짝 없는 서로게이트가 들어와도 길이는 같다(U+FFFD 한 글자)
    expect(clipText('\ud83d'.repeat(10), 4)).toContain('전체 10자 중 6자 생략');
  });

  it('Object.prototype 이름의 모델 id는 통계 없는 모델로 다룬다(옛 구현은 그 함수를 통계로 읽어 NaN이 됐다)', () => {
    const decision = routeModel([profile('constructor'), profile('toString'), profile('plain')], { prompt: 'add a button', intent: 'build' }, {});
    expect(decision.candidates.map((candidate) => candidate.quality)).toEqual([0.8, 0.8, 0.8]);
    expect(decision.candidates.every((candidate) => Number.isFinite(candidate.score))).toBe(true);
    // 같은 점수라 id 정렬: constructor < plain < toString
    expect(decision.candidates.map((candidate) => candidate.model.id)).toEqual(['constructor', 'plain', 'toString']);
  });

  it('aggregateModelStats는 __proto__·constructor id에서도 Object.prototype을 건드리지 않는다', () => {
    const stats = aggregateModelStats([
      { modelId: 'constructor', passed: true, latencyMs: 10 },
      { modelId: 'toString', passed: false, latencyMs: 20, costUsd: 0.5 },
      { modelId: '__proto__', passed: true, latencyMs: 30 },
    ]);
    expect(stats['constructor']).toEqual({ runs: 1, passes: 1, totalLatencyMs: 10, totalCostUsd: 0, pricedRuns: 0 });
    expect(stats['toString']).toEqual({ runs: 1, passes: 0, totalLatencyMs: 20, totalCostUsd: 0.5, pricedRuns: 1 });
    expect(Object.keys(stats)).toEqual(['constructor', 'toString', '__proto__']);
    expect(({} as { runs?: number }).runs).toBeUndefined();
    expect(Object.prototype.hasOwnProperty.call(Object.prototype, 'runs')).toBe(false);
  });

  it('baseUrl이 문자열이 아니면 거절한다(옛 구현은 URL로 읽히는 값에서 TypeError)', () => {
    expect(() => validateModelProfiles([{ ...profile('a'), baseUrl: ['https://x.com'] }])).toThrow('a.baseUrl이 올바른 URL이 아닙니다');
  });

  it('clearOldToolResults: 원본을 바꾸지 않고, 바꾸지 않은 메시지와 블록은 같은 참조이며, 모르는 필드는 그대로 간다', () => {
    const big = 'x'.repeat(50);
    const block = (id: string, extra: object = {}) => ({ type: 'tool_result' as const, tool_use_id: id, content: big, ...extra });
    const keep = { role: 'assistant' as const, content: [{ type: 'text' as const, text: 'hi' }] };
    const old = { role: 'user' as const, content: [block('a', { cache_control: { type: 'ephemeral' }, is_error: true, unknown: { deep: [1, 2] } }), { type: 'text' as const, text: 'note' }] };
    const recent = { role: 'user' as const, content: [block('b')] };
    const messages = [keep, old, recent];
    const before = JSON.stringify(messages);

    const result = clearOldToolResults(messages as never, { triggerTokens: 1, keepRecent: 1, clearAtLeastChars: 10 });

    expect(JSON.stringify(messages)).toBe(before);
    expect(result.messages).not.toBe(messages);
    expect(result.messages[0]).toBe(keep);
    expect(result.messages[2]).toBe(recent);
    expect(result.messages[1]).not.toBe(old);
    const cleared = (result.messages[1] as typeof old).content;
    expect(cleared[0]).toEqual({ type: 'tool_result', tool_use_id: 'a', content: '[이전 도구 결과 생략: 50자. 필요하면 같은 도구를 다시 부르세요]', cache_control: { type: 'ephemeral' }, is_error: true, unknown: { deep: [1, 2] } });
    expect(cleared[1]).toBe(old.content[1]);
    expect(Object.keys(cleared[0]!)).toEqual(['type', 'tool_use_id', 'content', 'cache_control', 'is_error', 'unknown']);
    expect(result.clearedCount).toBe(1);
    expect(result.clearedChars).toBe(50);

    // 비울 것이 없으면 같은 메시지 참조를 담은 새 배열이다
    const none = clearOldToolResults(messages as never, { triggerTokens: 1, keepRecent: 5, clearAtLeastChars: 10 });
    expect(none.messages).not.toBe(messages);
    expect(none.messages).toEqual(messages);
    expect(none.messages.every((message, index) => message === messages[index])).toBe(true);
  });

  it('상수와 문구는 Rust가 정한 값을 읽고, 단계 목록은 TS와 Rust가 같다', () => {
    expect(REPEAT_NOTE_PREFIX).toBe('(앞의 ');
    expect(CLEARED_TOOL_RESULT_PREFIX).toBe('[이전 도구 결과 생략: ');
    expect([...CLI_TIERS]).toEqual(native.cliTiers());
  });
});
